#!/usr/bin/env bash
# Prints the VM init script (AWS user_data, GCP startup-script) that installs Docker and runs testapp.
#   testapp/make-init.sh aws > init-aws.sh
# The testapp files are embedded, because the VM cannot clone this private repo. No secrets go in.
set -euo pipefail

served_by=${1:-}
case "$served_by" in
  aws|gcp|onprem) ;;
  *) echo "usage: $0 <aws|gcp|onprem>" >&2; exit 2 ;;
esac
src=$(cd "$(dirname "$0")" && pwd)

cat <<'EOF'
#!/bin/bash
# Generated by traffic/testapp/make-init.sh. GCP runs startup scripts on every boot, so each step is safe to repeat.
set -euxo pipefail

if ! command -v docker >/dev/null; then
  # unattended-upgrades holds the apt lock right after first boot, so wait for it instead of failing
  apt-get -o DPkg::Lock::Timeout=600 update
  DEBIAN_FRONTEND=noninteractive apt-get -o DPkg::Lock::Timeout=600 install -y docker.io curl
fi
mkdir -p /opt/testapp
EOF

for f in Dockerfile requirements.txt main.py; do
  echo "cat > /opt/testapp/$f <<'__TESTAPP_EOF__'"
  awk 1 "$src/$f"    # awk 1 adds the final newline if a file lacks one
  echo "__TESTAPP_EOF__"
done

cat <<EOF
docker build -t foxtrot-testapp /opt/testapp
if ! docker container inspect testapp >/dev/null 2>&1; then
  docker run -d --name testapp --restart unless-stopped \\
    -p 127.0.0.1:8000:8000 -e SERVED_BY=$served_by --stop-timeout 35 foxtrot-testapp
fi
EOF

# The check result lands in the boot log, readable without a shell:
# aws ec2 get-console-output / gcloud compute instances get-serial-port-output
cat <<'EOF'
set +x
code=000
for _ in $(seq 1 30); do
  code=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:8000/readyz || true)
  [ "$code" = 200 ] && break
  sleep 2
done
served=$(curl -s -o /dev/null -D - http://127.0.0.1:8000/ | awk -F': ' 'tolower($1)=="x-served-by" {print $2}' | tr -d '\r')
echo "testapp-check: readyz=$code x-served-by=$served"
EOF
